def _dense(sparse, width):
    return [sparse.get(i, "") for i in range(width)]


def grid():
    """The tab as the sheet API returns it: the header row, the rows, then the FALSE-only rows."""
    first_contact = HEADERS.index("First Contact")
    false_only = [""] * len(HEADERS)
    false_only[first_contact] = "FALSE"
    return ([list(HEADERS)] + [_dense(r, len(HEADERS)) for r in ROWS]
            + [list(false_only) for _ in range(FALSE_ONLY_ROWS)])


def master_grid():
    return [list(MASTER_PIPELINE_HEADERS)] + [_dense(r, len(MASTER_PIPELINE_HEADERS))
                                              for r in MASTER_PIPELINE_ROWS]


def tab(title="Outreach PoCs"):
    """The parsed tab (the real `_parse_values`)."""
    import gtm_sheet
    return gtm_sheet.SHEETS._parse_values(title, grid(), read_at=0.0)


def master_tab():
    import gtm_sheet
    return gtm_sheet.SHEETS._parse_values("Master Pipeline", master_grid(), read_at=0.0)
